 applets/colorpicker/main.xml              |   5 +
 applets/colorpicker/qml/HistoryModel.qml  |  10 +-
 applets/colorpicker/qml/configGeneral.qml |   8 +
 applets/colorpicker/qml/main.qml          | 397 +++++++++++-----------
 4 files changed, 222 insertions(+), 198 deletions(-)

diff --git a/applets/colorpicker/main.xml b/applets/colorpicker/main.xml
index c8238f585..a2a48a7ea 100644
--- a/applets/colorpicker/main.xml
+++ b/applets/colorpicker/main.xml
@@ -21,6 +21,11 @@
     <entry name="compactPreviewCount" type="Int">
       <default>1</default>
     </entry>
+    <entry name="historySize" type="Int">
+      <default>9</default>
+      <min>1</min>
+      <max>100</max>
+    </entry>
   </group>

 </kcfg>
